"""DuckDB execution engine.

The engine is the Phase 1 execution boundary. A `DuckDBTable` is a lazy SQL query
plus a validated schema and the source fingerprints it depends on. Steps compile new
SQL over the previous query, so nothing is materialised until a preview, count or
collect asks for rows.

Design rules
------------
* One connection per project session; every call is serialized by a lock.
* Schema is inferred from DuckDB (`DESCRIBE`) and mapped to kernel logical types.
* Source fingerprints make table fingerprints stable across runs.
* SQL is generated by the step registry, never accepted from untrusted project files
  without validation.
"""

from __future__ import annotations

import hashlib
import json
import re
import threading
import uuid
from collections.abc import Mapping, Sequence
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any

import duckdb
import pandas as pd
import pyarrow as pa

from ..kernel.schema import Column, DataType, Role, TableSchema
from ..kernel.table import TableData


class EngineError(RuntimeError):
    """Raised when the engine cannot execute or describe a query."""


_DUCKDB_TYPE_MAP: tuple[tuple[str, DataType], ...] = (
    ("BOOL", DataType.BOOLEAN),
    ("BOOLEAN", DataType.BOOLEAN),
    ("TINYINT", DataType.INTEGER),
    ("SMALLINT", DataType.INTEGER),
    ("INTEGER", DataType.INTEGER),
    ("BIGINT", DataType.INTEGER),
    ("HUGEINT", DataType.INTEGER),
    ("UTINYINT", DataType.INTEGER),
    ("USMALLINT", DataType.INTEGER),
    ("UINTEGER", DataType.INTEGER),
    ("UBIGINT", DataType.INTEGER),
    ("FLOAT", DataType.FLOAT),
    ("REAL", DataType.FLOAT),
    ("DOUBLE", DataType.FLOAT),
    ("DECIMAL", DataType.DECIMAL),
    ("NUMERIC", DataType.DECIMAL),
    ("VARCHAR", DataType.STRING),
    ("CHAR", DataType.STRING),
    ("TEXT", DataType.STRING),
    ("STRING", DataType.STRING),
    ("UUID", DataType.STRING),
    ("DATE", DataType.DATE),
    ("TIME", DataType.TIME),
    ("TIMESTAMP", DataType.DATETIME),
    ("DATETIME", DataType.DATETIME),
    ("INTERVAL", DataType.DURATION),
    ("BLOB", DataType.BINARY),
    ("BYTEA", DataType.BINARY),
    ("JSON", DataType.JSON),
    ("ENUM", DataType.CATEGORY),
    ("LIST", DataType.JSON),
    ("STRUCT", DataType.JSON),
    ("MAP", DataType.JSON),
    ("ARRAY", DataType.JSON),
    ("UNION", DataType.JSON),
)

_IDENTIFIER_SUFFIXES = ("_id", "_key", "_code", "_sku")


def dtype_for_duckdb(type_name: str) -> DataType:
    """Map a DuckDB type name to a kernel logical type."""

    normalized = type_name.strip().upper().split("(")[0].strip()
    for prefix, dtype in _DUCKDB_TYPE_MAP:
        if normalized == prefix:
            return dtype
    return DataType.UNKNOWN


def role_for_column(name: str, dtype: DataType) -> Role:
    lowered = name.casefold()
    if lowered in {"id", "key"} or lowered.endswith(_IDENTIFIER_SUFFIXES):
        return Role.IDENTIFIER
    if dtype in {DataType.DATE, DataType.DATETIME, DataType.TIME, DataType.DURATION}:
        return Role.TIME
    if dtype in {DataType.INTEGER, DataType.FLOAT, DataType.DECIMAL}:
        return Role.MEASURE
    if dtype in {DataType.STRING, DataType.CATEGORY, DataType.BOOLEAN}:
        return Role.DIMENSION
    return Role.DIMENSION


def _canonical(payload: Any) -> str:
    return json.dumps(
        payload,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
        default=str,
    )


def _normalize_sql(sql: str) -> str:
    return re.sub(r"\s+", " ", sql).strip()


def _sql_string(value: str) -> str:
    return "'" + str(value).replace("'", "''") + "'"


def _sql_path(path: Path) -> str:
    return _sql_string(str(path).replace("\\", "/"))


def file_fingerprint(path: Path, chunk_size: int = 1024 * 1024) -> str:
    digest = hashlib.sha256()
    with Path(path).open("rb") as handle:
        while chunk := handle.read(chunk_size):
            digest.update(chunk)
    return "sha256:" + digest.hexdigest()


def _frame_fingerprint(frame: pd.DataFrame) -> str:
    digest = hashlib.sha256()
    digest.update(_canonical([str(column) for column in frame.columns]).encode("utf-8"))
    digest.update(_canonical([str(dtype) for dtype in frame.dtypes]).encode("utf-8"))
    digest.update(str(frame.shape).encode("utf-8"))
    if len(frame):
        digest.update(pd.util.hash_pandas_object(frame, index=True).to_numpy().tobytes())
    return "sha256:" + digest.hexdigest()


def _arrow_fingerprint(table: pa.Table) -> str:
    sink = pa.BufferOutputStream()
    with pa.ipc.new_stream(sink, table.schema) as writer:
        writer.write_table(table)
    return "sha256:" + hashlib.sha256(sink.getvalue().to_pybytes()).hexdigest()


@dataclass(frozen=True, slots=True)
class SourceRef:
    """A data source that a table query depends on."""

    name: str
    kind: str
    fingerprint: str
    path: str | None = None

    def to_dict(self) -> dict[str, Any]:
        return {
            "name": self.name,
            "kind": self.kind,
            "fingerprint": self.fingerprint,
            "path": self.path,
        }


@dataclass(frozen=True, slots=True)
class DuckDBTable:
    """A lazy, schema-validated DuckDB query."""

    engine: DuckDBEngine = field(compare=False, hash=False, repr=False)
    sql: str
    schema: TableSchema
    sources: tuple[SourceRef, ...] = ()
    name: str | None = None

    def __post_init__(self) -> None:
        if not isinstance(self.engine, DuckDBEngine):
            raise TypeError("DuckDBTable requires a DuckDBEngine.")
        if not isinstance(self.sql, str) or not self.sql.strip():
            raise ValueError("DuckDBTable SQL must not be empty.")
        if not isinstance(self.schema, TableSchema):
            raise TypeError("DuckDBTable schema must be a TableSchema.")
        sources = tuple(self.sources)
        if any(not isinstance(source, SourceRef) for source in sources):
            raise TypeError("DuckDBTable sources must be SourceRef instances.")
        object.__setattr__(self, "sources", sources)

    @property
    def columns(self) -> tuple[str, ...]:
        return self.schema.names

    def count(self) -> int:
        return int(
            self.engine.query_one(f"SELECT count(*) FROM ({self.sql}) AS _count")[0]
        )

    def preview(self, limit: int = 100) -> TableData:
        if limit < 0:
            raise ValueError("limit must be >= 0.")
        rows = self.engine.query(
            f"SELECT * FROM ({self.sql}) AS _preview LIMIT {int(limit)}"
        )
        return TableData(self.schema, tuple(rows))

    def collect(self) -> TableData:
        return TableData(self.schema, tuple(self.engine.query(self.sql)))

    def to_pandas(self) -> pd.DataFrame:
        """Materialise this query as a pandas DataFrame (small/medium data only)."""

        return self.engine.execute(self.sql).df()

    def to_arrow(self) -> pa.Table:
        """Materialise this query as a pyarrow Table."""

        return self.engine.arrow(self.sql)

    def fingerprint(self) -> str:
        payload = {
            "sql": _normalize_sql(self.sql),
            "schema": self.schema.to_dict(),
            "sources": [source.to_dict() for source in self.sources],
        }
        return "sha256:" + hashlib.sha256(_canonical(payload).encode("utf-8")).hexdigest()

    def with_name(self, name: str) -> DuckDBTable:
        return DuckDBTable(self.engine, self.sql, self.schema, self.sources, name)

    def to_dict(self) -> dict[str, Any]:
        return {
            "name": self.name,
            "schema": self.schema.to_dict(),
            "fingerprint": self.fingerprint(),
            "sources": [source.to_dict() for source in self.sources],
        }


class DuckDBEngine:
    """A single DuckDB connection plus query helpers."""

    def __init__(self, database: str | Path = ":memory:", *, read_only: bool = False):
        self.database = str(database)
        self._lock = threading.RLock()
        self._connection = duckdb.connect(self.database, read_only=read_only)
        self._attached: dict[str, str] = {}
        self._views: set[str] = set()

    def close(self) -> None:
        with self._lock:
            self._connection.close()

    def __enter__(self) -> DuckDBEngine:
        return self

    def __exit__(self, *_: object) -> None:
        self.close()

    def execute(self, sql: str, params: Sequence[Any] | None = None) -> duckdb.DuckDBPyConnection:
        try:
            with self._lock:
                if params is None:
                    return self._connection.execute(sql)
                return self._connection.execute(sql, params)
        except duckdb.Error as exc:
            raise EngineError(f"Query failed: {exc}") from exc

    def query(self, sql: str, params: Sequence[Any] | None = None) -> list[tuple[Any, ...]]:
        try:
            with self._lock:
                cursor = (
                    self._connection.execute(sql)
                    if params is None
                    else self._connection.execute(sql, params)
                )
                return list(cursor.fetchall())
        except duckdb.Error as exc:
            raise EngineError(f"Query failed: {exc}") from exc

    def query_one(
        self, sql: str, params: Sequence[Any] | None = None
    ) -> tuple[Any, ...]:
        rows = self.query(sql, params)
        if not rows:
            raise EngineError("Query returned no rows.")
        return rows[0]

    def arrow(self, sql: str) -> pa.Table:
        """Materialise a query as Arrow without copying through Python rows."""

        try:
            with self._lock:
                return self._connection.sql(sql).to_arrow_table()
        except duckdb.Error as exc:
            raise EngineError(f"Query failed: {exc}") from exc

    def describe(self, sql: str, *, base_schema: TableSchema | None = None) -> TableSchema:
        """Infer a kernel schema from a SQL query without reading data."""

        try:
            with self._lock:
                rows = self._connection.execute(
                    f"DESCRIBE SELECT * FROM ({sql}) AS _describe"
                ).fetchall()
        except duckdb.Error as exc:
            raise EngineError(f"Cannot describe query: {exc}") from exc

        columns: list[Column] = []
        for row in rows:
            name, type_name, nullable, *_ = row
            dtype = dtype_for_duckdb(str(type_name))
            existing = None
            if base_schema is not None and str(name) in base_schema:
                existing = base_schema.column(str(name))
            columns.append(
                Column(
                    name=str(name),
                    dtype=dtype,
                    nullable=str(nullable).upper() != "NO",
                    role=existing.role if existing else role_for_column(str(name), dtype),
                    unit=existing.unit if existing else None,
                    description=existing.description if existing else None,
                    metadata=existing.metadata if existing else {},
                )
            )
        return TableSchema(columns=tuple(columns))

    def table(
        self,
        sql: str,
        *,
        name: str | None = None,
        sources: Sequence[SourceRef] = (),
        base_schema: TableSchema | None = None,
    ) -> DuckDBTable:
        schema = self.describe(sql, base_schema=base_schema)
        return DuckDBTable(self, sql, schema, tuple(sources), name)

    # -- sources -----------------------------------------------------------

    def from_parquet(self, path: str | Path, *, name: str | None = None) -> DuckDBTable:
        resolved = Path(path).resolve()
        if not resolved.is_file():
            raise FileNotFoundError(f"Parquet file not found: {resolved}")
        source = SourceRef(
            name=name or resolved.stem,
            kind="parquet",
            fingerprint=file_fingerprint(resolved),
            path=str(resolved),
        )
        sql = f"SELECT * FROM read_parquet({_sql_path(resolved)})"
        return self.table(sql, name=source.name, sources=(source,))

    def from_csv(
        self,
        path: str | Path,
        *,
        name: str | None = None,
        header: bool = True,
        delimiter: str = ",",
        quote: str = '"',
        encoding: str = "utf-8",
        sample_size: int = 20_480,
    ) -> DuckDBTable:
        resolved = Path(path).resolve()
        if not resolved.is_file():
            raise FileNotFoundError(f"CSV file not found: {resolved}")

        if encoding.lower().replace("_", "-") not in {"utf-8", "utf-8-sig"}:
            frame = pd.read_csv(
                resolved,
                sep=delimiter,
                quotechar=quote,
                encoding=encoding,
                header=0 if header else None,
            )
            return self.from_pandas(frame, name=name or resolved.stem, path=resolved)

        options = [
            f"header={str(header).lower()}",
            f"delim={_sql_string(delimiter)}",
            f"quote={_sql_string(quote)}",
            f"sample_size={int(sample_size)}",
        ]
        source = SourceRef(
            name=name or resolved.stem,
            kind="csv",
            fingerprint=file_fingerprint(resolved),
            path=str(resolved),
        )
        sql = (
            f"SELECT * FROM read_csv_auto({_sql_path(resolved)}, "
            + ", ".join(options)
            + ")"
        )
        return self.table(sql, name=source.name, sources=(source,))

    def from_json(self, path: str | Path, *, name: str | None = None) -> DuckDBTable:
        resolved = Path(path).resolve()
        if not resolved.is_file():
            raise FileNotFoundError(f"JSON file not found: {resolved}")
        source = SourceRef(
            name=name or resolved.stem,
            kind="json",
            fingerprint=file_fingerprint(resolved),
            path=str(resolved),
        )
        sql = f"SELECT * FROM read_json_auto({_sql_path(resolved)})"
        return self.table(sql, name=source.name, sources=(source,))

    def from_excel(
        self,
        path: str | Path,
        *,
        name: str | None = None,
        sheet_name: str | int | None = 0,
    ) -> DuckDBTable:
        resolved = Path(path).resolve()
        if not resolved.is_file():
            raise FileNotFoundError(f"Excel file not found: {resolved}")
        frame = pd.read_excel(resolved, sheet_name=sheet_name)
        return self.from_pandas(frame, name=name or resolved.stem, path=resolved)

    def from_pandas(
        self,
        frame: pd.DataFrame,
        *,
        name: str | None = None,
        path: Path | None = None,
    ) -> DuckDBTable:
        if not isinstance(frame, pd.DataFrame):
            raise TypeError("from_pandas expects a pandas DataFrame.")
        view = f"_pandas_{uuid.uuid4().hex}"
        with self._lock:
            self._connection.register(view, frame)
        self._views.add(view)
        source = SourceRef(
            name=name or view,
            kind="pandas",
            fingerprint=file_fingerprint(path) if path else _frame_fingerprint(frame),
            path=str(path) if path else None,
        )
        sql = f'SELECT * FROM "{view}"'
        return self.table(sql, name=source.name, sources=(source,))

    def from_arrow(self, table: pa.Table, *, name: str | None = None) -> DuckDBTable:
        if not isinstance(table, pa.Table):
            raise TypeError("from_arrow expects a pyarrow Table.")
        view = f"_arrow_{uuid.uuid4().hex}"
        with self._lock:
            self._connection.register(view, table)
        self._views.add(view)
        source = SourceRef(
            name=name or view,
            kind="arrow",
            fingerprint=_arrow_fingerprint(table),
            path=None,
        )
        sql = f'SELECT * FROM "{view}"'
        return self.table(sql, name=source.name, sources=(source,))

    def attach_duckdb(
        self,
        path: str | Path,
        *,
        alias: str,
        table: str,
    ) -> DuckDBTable:
        resolved = Path(path).resolve()
        if not resolved.is_file():
            raise FileNotFoundError(f"DuckDB file not found: {resolved}")
        if not re.match(r"^[A-Za-z_][A-Za-z0-9_]*$", alias):
            raise ValueError("DuckDB alias must be a simple identifier.")
        if alias not in self._attached:
            with self._lock:
                escaped = str(resolved).replace("\\", "/").replace("'", "''")
                self._connection.execute(
                    f"ATTACH '{escaped}' AS \"{alias}\" (READ_ONLY)"
                )
            self._attached[alias] = str(resolved)
        source = SourceRef(
            name=f"{alias}.{table}",
            kind="duckdb",
            fingerprint=file_fingerprint(resolved),
            path=str(resolved),
        )
        sql = f'SELECT * FROM "{alias}".{_quote_identifier(table)}'
        return self.table(sql, name=f"{alias}.{table}", sources=(source,))

    def from_records(
        self,
        rows: Sequence[Mapping[str, Any]],
        *,
        name: str | None = None,
    ) -> DuckDBTable:
        """Create a table from a list of same-shaped mappings (tests, small fixtures)."""

        return _literal_table(self, rows, name=name)


def _quote_identifier(name: str) -> str:
    if not isinstance(name, str) or not name:
        raise ValueError("Identifier must be a non-empty string.")
    return '"' + name.replace('"', '""') + '"'


# A tiny helper used by tests and callers that already have a mapping of literals.
def _literal_table(
    engine: DuckDBEngine,
    rows: Sequence[Mapping[str, Any]],
    *,
    name: str | None = None,
) -> DuckDBTable:
    if not rows:
        raise ValueError("rows must not be empty.")
    columns = list(rows[0].keys())
    values = []
    for row in rows:
        if list(row.keys()) != columns:
            raise ValueError("All literal rows must have the same columns.")
        values.append(
            "(" + ", ".join(_sql_literal(row[column]) for column in columns) + ")"
        )
    select_list = ", ".join(_quote_identifier(column) for column in columns)
    sql = f"SELECT * FROM (VALUES {', '.join(values)}) AS _v({select_list})"
    return engine.table(sql, name=name or "literal")


def _sql_literal(value: Any) -> str:
    if value is None:
        return "NULL"
    if isinstance(value, bool):
        return "TRUE" if value else "FALSE"
    if isinstance(value, float):
        # DuckDB parses a bare ``10.0`` literal as DECIMAL. Cast explicitly so
        # Python floats keep their DOUBLE identity when building literal tables.
        if value != value or value in {float("inf"), float("-inf")}:
            return "NULL"
        return f"CAST({value!r} AS DOUBLE)"
    if isinstance(value, int):
        return repr(value)
    if isinstance(value, str):
        return _sql_string(value)
    return _sql_string(str(value))


# Public aliases used by the SQL compiler in `data_studio.steps`.
quote_identifier = _quote_identifier
sql_literal = _sql_literal
sql_string = _sql_string
sql_path = _sql_path

